export function Topbar({
  title = "{{title}}",
  density = "{{density}}",
  accent = "{{accent}}",
  search = {{search}},
}) {
  const compact = density === "compact";
  return (
    <div style={{ display: "flex", alignItems: "center", gap: compact ? 8 : 12, fontFamily: "system-ui, sans-serif", fontSize: compact ? 12 : 13, color: "#FAF7F2", background: accent, padding: compact ? "6px 12px" : "12px 16px", boxSizing: "border-box" }}>
      <span style={{ fontWeight: 700 }}>{title}</span>
      {search && <input type="text" placeholder="Search..." style={{ flex: 1, maxWidth: 220, boxSizing: "border-box", border: "1px solid #FAF7F244", background: "#FAF7F21a", color: "#FAF7F2", borderRadius: 6, padding: "6px 10px", font: "inherit" }} />}
      <div style={{ display: "flex", gap: 8, marginLeft: "auto" }}>
        <button type="button" style={{ background: "transparent", border: "none", color: "#FAF7F2", cursor: "pointer", fontSize: 14, padding: "4px 8px", borderRadius: 6 }}>＋</button>
        <button type="button" style={{ background: "transparent", border: "none", color: "#FAF7F2", cursor: "pointer", fontSize: 14, padding: "4px 8px", borderRadius: 6 }}>⚙</button>
      </div>
    </div>
  );
}
